head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp = js_market;

// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
// 
// ********************************************************************

scwin.gUpDepCd;
scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.gScnNm;
scwin.vScrenID = 'ULDSTF26900.xml';X < !공시상세--;
목록검색;
클릭-- > function() {
    var vIsurCd = $c.stf.getObjectValue(txb_isur_cd);
    var vIcnb_lst_yn = $c.stf.getObjectValue(chb_lst_yn);
    var vIcnb_ldxAct_yn = $c.stf.getObjectValue(chb_IdxAct_yn);


    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    // 조회일 구분
    if (scwin.getChkValue(chb_lst_yn) == 0 && scwin.getChkValue(chb_IdxAct_yn) == 0) {
        $c.win.alert("조회공시선택은 한개이상 선택하십시오.");
        chb_lst_yn.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) == false) {
        return;
    }
    fn_Search();
} < !공시상세--;
클릭-- > function() {
    var url = "";
    url = "/IdxDisclosureSearch.do?method=listIdxDsclSrch" + "&inputMessageId=IDXDSCLDETAILLIST_IN" + "&outputMessageId=IDXDSCLDETAILLIST_OUT" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&DISCLS_TP_CD=" + $c.stf.getObjectValue(rdo_DSCL_ID) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&LST_YN=" + scwin.getChkValue(chb_lst_yn) + "&IDXACT_YN=" + scwin.getChkValue(chb_IdxAct_yn) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_DsclList.DataID = encodeURI(url);
    dts_DsclList.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_getDate = function() {
    var url = "/IdxDisclosureSearch.do?method=idxDsclSdate" + "&inputMessageId=SDATE_IN" + "&outputMessageId=SDATE_OUT";
    dts_sDate.DataID = encodeURI(url);
    dts_sDate.reset();
    //ShowWin(grd_Grid);

};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};
scwin.setChkValue = function(obj, booleanVal) {
    //return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);
};
scwin.fn_resetParam = function() {
    vCurrDate = scwin.fn_getDate();
    $c.stf.setObjectValue(txb_isur_cd, "");
    $c.stf.setObjectValue(txb_com_abbrv, "");
    scwin.setChkValue(chb_IdxAct_yn, true);
    scwin.setChkValue(chb_lst_yn, true);
    $c.stf.setObjectValue(rdo_DSCL_ID, "2");
    dts_DsclList.removeAll();
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclList.getCellData(eval(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DsclList.getCellData(eval(obj), "FORM_CD");
    scwin.gFormVer = dts_DsclList.getCellData(eval(obj), "FORM_VER");
    scwin.gIsurCd = dts_DsclList.getCellData(eval(obj), "ISUR_CD");
    //alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};
scwin.dts_DsclList_OnLoadError = function() {
    $c.stf.alert_error(dts_DsclList);
};
scwin.dts_DsclList_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.dts_sDate_OnLoadError = function() {
    $c.stf.alert_error(dts_sDate);
};
scwin.dts_sDate_OnLoadCompleted = function(rowcount) {
    if (dts_sDate.getCellData(0, "SDATE_DD") == "") {
        var vCurDate = $c.ut.cGetToday("yyyymmdd");
        //edt_FromDate.text = cGetMinusDate2(vCurDate, 7); 	// 일주일전 날짜
        edt_FromDate.setValue(vCurDate); // 현재날짜
        edt_ToDate.setValue(vCurDate); // 현재날짜

    } else {
        edt_FromDate.setValue(dts_sDate.getCellData(0, "SDATE_DD"));
        edt_ToDate.setValue(dts_sDate.getCellData(0, "SDATE_DD"));
    }
    fn_Search();
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    //Grd_com_isur.style.display ="";
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.btn_Excel_onclick = function() {
    $c.data.downloadGridViewExcel(grd_Grid, "지수공시상세검색 목록", "", "8");
};
scwin.btn_Snd_onclick = function() {
    location.href = "/dsclsrch/idxDsclsrch.xls";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.grd_Grid_OnLButtonDblClk = function(row, colid, xpos, ypos) {
    scwin.fn_setContnId(row);
    if (colid == "DISCLS_NM") {
        //2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R", scwin.vScrenID);
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_resetParam();

    //fn_CheckCond();

};
